#include <iostream>
#include <utility>
#include <vector>

std::pair<long long, long long> min_max(const std::vector<long long> &v) {
    long long lo = v[0], hi = v[0];
    for (long long x : v) {
        if (x < lo) {
            lo = x;
        }
        if (x > hi) {
            hi = x;
        }
    }
    return {lo, hi};
}

int main() {
    std::vector<long long> v;
    long long x;
    while (std::cin >> x) {
        v.push_back(x);
    }
    if (v.empty()) {
        std::cout << "пусто\n";
        return 0;
    }
    auto [lo, hi] = min_max(v);
    std::cout << "минимум " << lo << ", максимум " << hi << '\n';
    return 0;
}

